export const TOWER_SERVICES = [
  { type: "Assassin's and thieves' services", description: "Killing and stealing, priced by the status of the victim, from the lowest commoner up through merchants, knights, lords, nobles, royals, and high-level wizards and clerics. Few questions asked; the work is always performed quickly. The book warns that using these services invites retaliation in kind.", payment: "Half paid down, the rest after the deed." },
  { type: "Wizard's services", description: "Spellcasting for hire; identifying a magic item; supplying scrolls. Wish-type spells are never available through these services. Alternative payment: a wizard will settle for an adventure instead — go and bring back a special item.", payment: "Charged by the level of the spell plus components; identification charged as an advance plus a share of the item's value once identified; scrolls charged by spell level. No figures are recorded here." },
  { type: "Cleric's services", description: "Spellcasting for hire; divination and guidance, with a quest owed to the cleric's order if guidance is actually given; supplying scrolls. Same-faith customers pay a reduced rate. Spells above a certain level are not sold for coin at all — the asker must take a quest for the cleric's order for each such spell.", payment: "Charged by spell level; divination charged per question, plus a quest if guidance is given. No figures are recorded here." },
  { type: "Fighter's services", description: "Fighters hire out for battle as retainers, not as one-off purchases, with the rate rising steeply by the fighter's experience band. Fighters working for found always take their pick of any treasure from a battle first.", payment: "Paid in advance, rising by experience band from a pittance for the least experienced to a large weekly sum for veterans. No figures are recorded here." },
];

export const TOWER_HOOKS = [
  { id: "your-wizard-uncle", title: "Your Wizard Uncle", premise: "A travelling merchant delivers an official parchment and a very large brass key to one party member: his wizard uncle has left him his tower and everything in it, with the warning that some of the contents are quite dangerous. The uncle was known for creating undead just because he could.", hook: "Inherit a wizard's tower, contents unknown and dangerous.", npcs: ["Wizard Danton"], places: ["a large city", "the wizard uncle's tower"] },
  { id: "newly-built-orc-tower", title: "Newly Built Orc Tower", premise: "Orcs have built a tower on a cliff above a town in a single night. The town guard cannot assault that kind of fortification; the commander calls for adventurers to scale the cliff and take out the orcs, offering payment plus found goods. The tower bristles with arrow slits and apparent siege engines on the roof; people are leaving the city; messages to the King have gone unanswered.", hook: "Scale a cliff and clear a tower that appeared overnight.", npcs: ["town guard commander", "the King"], places: ["a town", "a cliff above the town", "the orc tower"] },
  { id: "teleporter", title: "Teleporter", premise: "In a favourite dungeon section the party revisits often, a new man-sized purple mirror has appeared, glowing, set against a wall. Thrown objects bounce off; only when someone holding something touches it does it activate, and the toucher glows purple and vanishes.", hook: "Do the rest touch the mirror, or wait while something beyond it deals with their friend?", npcs: [], places: ["a familiar dungeon"] },
  { id: "tunnel-of-terror", title: "Tunnel of Terror", premise: "In a familiar dungeon, the party finds a new tunnel or secret door they have never seen, its earth walls freshly dug and wet. Following it, they come up inside the next deadly tower. No explanation is given for who dug it.", hook: "Follow a freshly dug tunnel and come up inside a deadly tower.", npcs: [], places: ["a familiar dungeon", "a deadly tower"] },
  { id: "tower-in-the-sky", title: "Tower in the Sky", premise: "A huge cloud floats into the area, and on top of it sits what appears to be a stone tower. It stops and hovers near the city below; griffons and even a blue dragon are seen flying around it; townspeople flee in panic. The party must quest for flying magic to be first to explore it. The tower is far above, and the clouds hide its base.", hook: "Quest for flying magic to reach a tower hovering on a cloud.", npcs: [], places: ["a city", "a tower on a cloud"] },
  { id: "fight-in-the-wilds", title: "Fight in the Wilds", premise: "During a wilderness battle with a monster band, the party sees two creatures carrying off a large chest. After the fight, a clear trail leads deeper into an old, dark forest where the sun does not reach through the leaves, to a valley where a tower barely rises among the tall trees.", hook: "Follow the trail of a carried-off chest to a tower in a dark valley.", npcs: [], places: ["an old, dark forest", "a valley", "a tower among tall trees"] },
  { id: "the-magistrates-tower-problem", title: "The Magistrate's Tower Problem", premise: "A town guard detachment politely but firmly summons the party to the magistrate: goblin bands are attacking merchants travelling between cities, and the party is asked to scout north of the city and find the goblin stronghold. Payment plus found goods is offered for information; eliminating the problem earns special favours from the city. The magistrate is content with information alone — the party is not ordered to fight.", hook: "Scout for a goblin stronghold; fighting is not ordered.", npcs: ["the magistrate"], places: ["a city", "north of the city", "a goblin stronghold"] },
  { id: "slavers", title: "Slavers", premise: "A young fighter approaches the party: slavers captured his family while he was away, and he has tracked them to a tower in a valley. He believes the bulk of the slaver band is elsewhere and wants to rush the tower before the family can be sold or harmed. He has little coin but offers a prized family heirloom weapon in trade for the whole party's help.", hook: "Rush a slaver tower before a family can be sold.", npcs: ["a young fighter"], places: ["a tower in a valley"] },
  { id: "treasure-map", title: "Treasure Map", premise: "In a pile of treasure, the party finds a chest with a difficult lock and a deadly trap. Inside are two maps: one into the mountains, one of a tower labelled tower of gold. The party recognises roughly where that tower could be. The catch, written tiny by the tower drawing: the word giant.", hook: "Follow a map to a tower of gold — with giant written beside it.", npcs: [], places: ["the mountains", "a tower of gold"] },
  { id: "dreaming-of-adventure", title: "Dreaming of Adventure", premise: "Every party member begins having the same dream: walking into a tower and dying at the hands of some monster, night after night. Sleep suffers and the party grows weaker. From the dreams they believe the tower lies in the hills south of their city, and they buy special equipment against the poison gas and deadly plants that fill the dreams. The sender of the dreams is never identified.", hook: "A shared nightmare points to a tower in the southern hills.", npcs: [], places: ["hills south of the city", "a tower"] },
  { id: "sages-call", title: "Sage's Call", premise: "A sage has found notes about a famous wizard's tower, lost centuries ago after a failed wizard experiment. He has directions to it and a spell to uncover its portal, and wants first pick of magic items plus all the silver found. He is no fighter, which is why he needs the party, and he promises hidden chambers filled with wizard devices, components, rough-cut gems, and gold bars — if the tower is still there.", hook: "Help a sage find a lost wizard's tower, if it survived.", npcs: ["a sage"], places: ["a lost wizard's tower"] },
  { id: "time-of-the-full-moon", title: "Time of the Full Moon", premise: "Around the full moon only, sheep and cattle near the city are devoured; the rest of the month the flocks are untouched. The mayor fears werewolves and offers a reward plus special silver weapons to whoever kills whatever is causing it. Three other groups have tried in the last six months, and none came back from the fields north of the city.", hook: "Find what devours the flocks at the full moon, where three groups vanished.", npcs: ["the mayor"], places: ["a city", "fields north of the city"] },
  { id: "merchant-and-goods", title: "Merchant and Goods", premise: "A rich merchant caravan is a month overdue, and its owners in the city are worried. They want bravos to backtrack it, offering half the worth of the caravan goods plus all found during the quest. The route has two difficult passages: a high mountain pass that always has snow, and a sometimes-hard-to-find oasis in the middle of the desert.", hook: "Backtrack an overdue caravan through a snowy pass and a desert oasis.", npcs: ["caravan owners"], places: ["a city", "a high mountain pass", "a desert oasis"] },
  { id: "royals", title: "Royals", premise: "A Lord's coach drives up and a handsome young well-dressed man introduces himself as Lord Ronald, who has an estate in the mountains north of the city. Someone has dared to put a tower in one of his vales, and he is furious; his gamekeepers sent to remove the occupants were eaten. He wants the tower cleaned out before the full moon in three weeks, offering payment plus anything found in the tower, and offers to upgrade each party member's arms and armour from his castle armoury.", hook: "Clear a tower from Lord Ronald's vale before the full moon.", npcs: ["Lord Ronald"], places: ["mountains north of the city", "a vale", "Lord Ronald's castle"] },
  { id: "a-simple-thing", title: "A Simple Thing", premise: "Returning to the city tired after a long quest, the party is jostled by ruffians in the street and thinks nothing of it — until each finds a note on their bed: if they want their things returned, come talk to the Dodger down at the docks. Each has had a very valuable item stolen. At the docks they meet the head of the thieves' guild at an inn, who explains that a tower in the city has had no one come in or out for months; his own people sent in never came out. He returns their things, offers healing and a healing potion each as partial payment, and asks them to enter the tower and find out what happened to his people — noting, politely, that his people can always take the things back if they refuse.", hook: "The theft was a lever, not the crime — the real job is the silent tower.", npcs: ["the Dodger"], places: ["a city", "the docks", "an inn", "a silent tower in the city"] },
  { id: "a-bad-day-for-the-giant", title: "A Bad Day for the Giant", premise: "Travelling the King's road, the party finds a shiny new copper coin, then silver pieces in the grass, then a gold piece on a deer trail — a trail of dropped coins leading to a distant, very large moving figure: a giant with a sack, leaking shiny metal from a rip in the bottom. The party need not fight the giant; the hook is following the trail of what falls from the sack and hoping the sack held more interesting treasure.", hook: "Follow a giant's leaking sack and see what else falls out.", npcs: [], places: ["the King's road", "a deer trail"] },
  { id: "a-relative-problem", title: "A Relative Problem", premise: "In thirty days, the party member's brother will hang in the middle of town for a crime he did not commit. He and his long-time partner went into the wilds months ago; the brother came back with a huge chest of treasure, the partner did not, and the partner's relatives had enough connections to have the brother tried and sentenced. The brother gives the party a map to a hidden tower in the mountains, where he says they will find evidence of how the partner died — along with many magical traps and much trouble. It takes at least five days to get there on fast horses, so the clock is real.", hook: "Reach a hidden mountain tower in time to clear an innocent brother.", npcs: ["the party member's brother", "the brother's partner"], places: ["a town", "the wilds", "a hidden tower in the mountains"] },
  { id: "just-like-it-was-yesterday", title: "Just Like It Was Yesterday", premise: "The hook is written as a false memory or vision: arrows fly from a tower, the party bashes in the door, fights guards on the lower chamber, finds traps and unusual treasure, climbs to tougher guards and better treasure on the second level, retreats before a third level they doubt they can survive — and wakes suddenly. The tower of the dream stands on a hill, several miles distant. The party goes to market to buy defensive equipment, including pavises, in case the dreams are true. This is the second dream hook in the book; hook 10 is a shared nightmare sent by an unknown sender, this one is a prophetic-feeling replay of a tower assault.", hook: "A dream replays a tower assault — is it a warning or a prophecy?", npcs: [], places: ["a hill", "a tower"] },
  { id: "images-appear-smaller-than-you-think", title: "Images Appear Smaller Than You Think", premise: "Breaking into a place of wizards, the party finds a model of a tower on a glowing table, showing three levels with tiny figures on each: an orc tower with guardian orcs, and at the top a wizard and several powerful-looking orcs. One party member touches the model; a burst of green light blinds the party, and they wake as the tower's inhabitants — the viewpoint character is now Gror-org, the orc clan chief, and the tower is about to be attacked by human clerics and their followers. The party must order the defence, knowing that if they die in these new forms, their old bodies are likely dead too.", hook: "Body-swapped into an orc tower about to be attacked — order its defence.", npcs: ["Gror-org"], places: ["a place of wizards", "an orc tower"] },
  { id: "mirror-mirror-on-the-wall-what-the-heck-are-you", title: "Mirror Mirror on the Wall, What the Heck Are You?", premise: "Behind a tapestry, the party finds a large mirror that first shows only their image, then a room, glowing golden. A hand passes through it. On the other side: a table covered in crystal potion bottles and wizard's things. The hook is the choice of how bold to be — rush in and out, or take a large force through and see what kind of fight happens? Distinct from the teleporter mirror: this mirror is a doorway to a room, not a one-way vanishing device.", hook: "A mirror opens onto a wizard's room — how bold should the party be?", npcs: [], places: ["a room behind a tapestry"] },
];

