// Helpers — all pure, all returning copies or fresh arrays.
export function towers() { return TOWERS.map((t) => ({ ...t })); }
export function towerById(id) { return TOWERS.find((t) => t.id === id) || null; }
export function hooks() { return TOWER_HOOKS.map((h) => ({ ...h, npcs: [...h.npcs], places: [...h.places] })); }
export function hookById(id) { return TOWER_HOOKS.find((h) => h.id === id) || null; }
export function services() { return TOWER_SERVICES.map((s) => ({ ...s })); }
export function npcsByBand(band) { return TOWER_NPCS.filter((n) => n.band === band).map((n) => ({ ...n })); }
export function monstersByBand(band) { return TOWER_MONSTERS.filter((m) => m.band === band).map((m) => ({ ...m })); }
export function playableMonsters() { return TOWER_MONSTERS.filter((m) => m.status === "2024" || m.status === "reskin").map((m) => ({ ...m })); }
export function blockedMonsters() { return TOWER_MONSTERS.filter((m) => m.status === "blocked").map((m) => ({ ...m })); }
export function treasuresByTheme(theme) { return TOWER_TREASURES.filter((t) => t.theme === theme).map((t) => ({ ...t })); }
export function trapsByCategory(category) { return TOWER_TRAPS.filter((t) => t.category === category).map((t) => ({ ...t })); }
